import sys
import json
import pickle
from scipy.spatial.distance import euclidean
from vptree import VPTree

def load_vp_tree(vp_tree_path, photo_ids_path):
    """ Loads the VP-Tree and photo IDs from files. """
    with open(vp_tree_path, 'rb') as f:
        vp_tree = pickle.load(f)
    with open(photo_ids_path, 'r') as f:
        photo_ids = json.load(f)
    return vp_tree, photo_ids

def search_vp_tree(vp_tree, photo_ids, query_features, n):
    """ Searches the VP-Tree for the nearest neighbors of the query features. """
    # Find the nearest neighbors
    distances_indices = vp_tree.get_n_nearest_neighbors(query_features, n)
    
    # Extract the indices (position in the combined_features list)
    indices = [photo_ids.index(idx) for _, idx in distances_indices]

    # Extract the photo IDs of the nearest neighbors
    nearest_photo_ids = [photo_ids[idx] for idx in indices]

    return nearest_photo_ids

